mapper.select:
SELECT DATE_FORMAT(t1.`patrol_time`,#{param.dateExp}) as period, COUNT( DISTINCT t1.`id` ) AS total_num FROM `camera_patrol_record_device` t1
and t1.`result` = #{param.patrolResult}
and t1.`patrol_time` >= #{param.period.begin}
and t1.`patrol_time` <= #{param.period.end}
GROUP BY DATE_FORMAT( t1.`patrol_time`,#{param.dateExp})

SELECT `device_id` as id, `device_name` as name, COUNT(1) as total_num FROM `camera_patrol_record_device`
and `patrol_time` >= #{param.period.begin}
and `patrol_time` <= #{param.period.end}
GROUP BY `device_id`,`device_name` ORDER BY COUNT(1) desc limit #{param.topSize}
